# From v6's `test/rules/discrete_transition/in_tests.jl`.
@testitem "rules:DiscreteTransition:in:Variational Bayes: (q_out::Any, q_a::DirichletCollection)" tags = [
    :rules,
] begin
    using DiscreteTransitionMessagePassingRules, MessagePassingRulesTestUtils, MessagePassingRulesBase, BayesBase, ExponentialFamily, Distributions, LinearAlgebra, Random
    using BayesBase: tiny

    diageye(n) = Matrix{Float64}(I, n, n)
    @test_message_update_rule(
        node = DiscreteTransition, target = :in, check_type_promotion = false,
        cases = [
            (
                q = (
                    out = PointMass([0.1, 0.4, 0.5]), a = DirichletCollection(
                        [0.2 0.1 0.7; 0.4 0.3 0.3; 0.1 0.6 0.3]
                    ),
                ),
            ) => Categorical(
                [
                    0.03245589526827472, 0.5950912160314408, 0.37245288870028453,
                ]
            ),
            (q = (out = PointMass([0.0, 1.0, 0.0]), a = DirichletCollection(diageye(3) .+ tiny)),) => Categorical([0.0, 1.0, 0.0]),
        ],
    )
end

