@testitem "rules:DiscreteTransition:in: 2-interface PointMass rule matches exp-then-normalise" tags = [
    :rules,
] begin
    using DiscreteTransitionMessagePassingRules, MessagePassingRulesTestUtils, MessagePassingRulesBase, BayesBase, ExponentialFamily, Distributions, LinearAlgebra, Random
    using BayesBase: tiny

    diageye(n) = Matrix{Float64}(I, n, n)

    # v6's 2-interface rule computed `eloga' * probvec(q_out)`, unnormalised log probabilities,
    # and exponentiated them with `exp` then `normalize!` where its siblings used `softmax!`
    # (issue #627). Both agree on these inputs, at extreme `q_a` scales too; the generic rule
    # is pinned to the naive form here.
    @testset "agrees with the naive form across a wide range of q_a scales" begin
        q_out = PointMass([0.1, 0.4, 0.5])

        for q_a in (
                PointMass([0.2 0.4 0.1; 0.1 0.3 0.6; 0.7 0.3 0.3]),
                PointMass([1.0e-8 1.0 1.0; 1.0 1.0e-8 1.0; 1.0 1.0 1.0e-8]),
                PointMass([1.0e8 1.0 1.0; 1.0 1.0e8 1.0; 1.0 1.0 1.0e8]),
                PointMass(diageye(3) .+ tiny),
            )
            eloga = mean(Base.Broadcast.BroadcastFunction(BayesBase.clamplog), q_a)
            naive = exp.(eloga' * probvec(q_out))
            naive ./= sum(naive)

            msg = call_message_update_rule(DiscreteTransition, :in; q = (out = q_out, a = q_a))

            p = probvec(msg)
            @test p ≈ naive
            @test all(isfinite, p)
            @test sum(p) ≈ 1
        end
    end
end

